function validate([n, restrictions, requests]) {
  if (!Number.isInteger(n) || n < 2 || n > 1000) return 'n is between 2 and 1000.';
  if (!Array.isArray(restrictions) || restrictions.length > 1000) return 'restrictions has at most 1000 pairs.';
  if (!Array.isArray(requests) || requests.length < 1 || requests.length > 1000) return 'requests needs 1 to 1000 pairs.';
  for (const list of [restrictions, requests]) {
    for (const p of list) {
      if (!Array.isArray(p) || p.length !== 2) return 'Each pair has two people.';
      const [a, b] = p;
      if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'People are numbered 0 to n - 1.';
      if (a === b) return 'A pair names two different people.';
    }
  }
  return null;
}

