function friendRequests(n, restrictions, requests) {
  const parent = Array.from({ length: n }, (_, i) => i);

  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  const result = [];
  for (const [u, v] of requests) {
    const rootU = find(u);
    const rootV = find(v);
    let allowed = true;
    if (rootU !== rootV) {
      for (const [x, y] of restrictions) {
        const rootX = find(x);
        const rootY = find(y);
        if ((rootX === rootU && rootY === rootV) || (rootX === rootV && rootY === rootU)) {
          allowed = false;
          break;
        }
      }
    }
    if (allowed) parent[rootV] = rootU;
    result.push(allowed);
  }
  return result;
}

