function friendRequests(n, restrictions, requests) {
  const adj = Array.from({ length: n }, () => []);
  const label = () => {
    const comp = new Array(n).fill(-1);
    for (let s = 0; s < n; s++) {
      if (comp[s] !== -1) continue;
      comp[s] = s;
      const stack = [s];
      while (stack.length) {
        const a = stack.pop();
        for (const b of adj[a]) if (comp[b] === -1) { comp[b] = s; stack.push(b); }
      }
    }
    return comp;
  };
  const out = [];
  for (const [u, v] of requests) {
    adj[u].push(v);
    adj[v].push(u);
    const comp = label();
    const ok = restrictions.every(([x, y]) => comp[x] !== comp[y]);
    if (!ok) { adj[u].pop(); adj[v].pop(); }
    out.push(ok);
  }
  return out;
}

