function generate(rand, size) {
  const large = size === 'large';
  const n = large ? (rand() < 0.5 ? 1000 : 50 + Math.floor(rand() * 200)) : 2 + Math.floor(rand() * 7);
  const pair = () => {
    const a = Math.floor(rand() * n);
    let b = Math.floor(rand() * (n - 1));
    if (b >= a) b++;
    return [a, b];
  };
  const r = large ? 1000 : Math.floor(rand() * 7);
  const q = large ? 1000 : 1 + Math.floor(rand() * 10);
  const restrictions = Array.from({ length: r }, pair);
  const requests = Array.from({ length: q }, pair);
  return [n, restrictions, requests];
}
